"""Tests for the official_60 dataset generated by scripts/prepare_official_dataset.py.

Validates record counts, field integrity, and ID consistency across all
JSONL files under data/official_60/.
"""
import json
from pathlib import Path

# ── Helpers ──────────────────────────────────────────────────────────────

BASE_DIR = Path(__file__).resolve().parent.parent.parent  # backend/tests -> project root
DATA_DIR = BASE_DIR / "data" / "official_60"


def load_jsonl(path):
    """Read a JSONL file and return a list of parsed dicts (skipping blank lines)."""
    with open(path, "r", encoding="utf-8") as f:
        return [json.loads(line) for line in f if line.strip()]


# ── Tests ────────────────────────────────────────────────────────────────


class TestOfficialDataset:
    """Integrity checks for the official_60 dataset."""

    def test_models_jsonl_count(self):
        """data/official_60/models.jsonl must contain exactly 60 records."""
        models = load_jsonl(DATA_DIR / "models.jsonl")
        assert len(models) == 60, f"Expected 60 models, got {len(models)}"

    def test_query_model_eval_count(self):
        """data/official_60/query_model_eval.jsonl must contain exactly 417 records."""
        records = load_jsonl(DATA_DIR / "query_model_eval.jsonl")
        assert len(records) == 417, f"Expected 417 records, got {len(records)}"

    def test_split_counts(self):
        """Train / test / val splits must match expected sizes (291 / 62 / 64)."""
        train = load_jsonl(DATA_DIR / "queries_train.jsonl")
        test = load_jsonl(DATA_DIR / "queries_test.jsonl")
        val = load_jsonl(DATA_DIR / "queries_val.jsonl")
        assert len(train) == 291, f"Expected 291 train queries, got {len(train)}"
        assert len(test) == 62, f"Expected 62 test queries, got {len(test)}"
        assert len(val) == 64, f"Expected 64 val queries, got {len(val)}"

    def test_duplicate_model_deduplicated(self):
        """models.jsonl must have 60 unique model_names and contain exactly one
        instance of the duplicate model '小微企业违约概率B卡模型'."""
        models = load_jsonl(DATA_DIR / "models.jsonl")
        model_names = [m["model_name"] for m in models]
        unique_names = set(model_names)
        assert len(unique_names) == len(models) == 60, (
            f"Expected 60 unique model_names, got {len(unique_names)} "
            f"(total models: {len(models)})"
        )
        dup_count = sum(1 for n in model_names if n == "小微企业违约概率B卡模型")
        assert dup_count == 1, (
            f"Expected exactly 1 model named '小微企业违约概率B卡模型', "
            f"but found {dup_count}"
        )

    def test_source_type_official_dataset(self):
        """All records in models.jsonl and query_model_eval.jsonl must have
        source_type == 'official_dataset'."""
        models = load_jsonl(DATA_DIR / "models.jsonl")
        for m in models:
            assert m.get("source_type") == "official_dataset", (
                f"Model {m.get('model_id', '?')} has source_type "
                f"'{m.get('source_type')}', expected 'official_dataset'"
            )

        queries = load_jsonl(DATA_DIR / "query_model_eval.jsonl")
        for q in queries:
            assert q.get("source_type") == "official_dataset", (
                f"Query {q.get('query_id', '?')} has source_type "
                f"'{q.get('source_type')}', expected 'official_dataset'"
            )

    def test_gold_model_ids_resolvable(self):
        """Every gold_model_id in query_model_eval.jsonl must reference an
        existing model_id in models.jsonl."""
        models = load_jsonl(DATA_DIR / "models.jsonl")
        model_ids = {m["model_id"] for m in models}

        queries = load_jsonl(DATA_DIR / "query_model_eval.jsonl")
        unresolved = []
        for q in queries:
            for gid in q.get("gold_model_ids", []):
                if gid not in model_ids:
                    unresolved.append((q.get("query_id", "?"), gid))

        assert not unresolved, (
            f"Found {len(unresolved)} unresolved gold_model_ids: {unresolved}"
        )

    def test_official_model_ids_prefix(self):
        """Every model_id in models.jsonl must start with 'OFFICIAL_'."""
        models = load_jsonl(DATA_DIR / "models.jsonl")
        for m in models:
            mid = m.get("model_id", "")
            assert mid.startswith("OFFICIAL_"), (
                f"model_id '{mid}' does not start with 'OFFICIAL_'"
            )

    def test_no_legacy_model_ids_in_official(self):
        """No model_id in models.jsonl should start with legacy prefixes
        (RISK_, MKT_, OPS_)."""
        models = load_jsonl(DATA_DIR / "models.jsonl")
        legacy_prefixes = ("RISK_", "MKT_", "OPS_")
        for m in models:
            mid = m.get("model_id", "")
            assert not mid.startswith(legacy_prefixes), (
                f"Found legacy model_id '{mid}' in official dataset"
            )
